={{ (() => {
  const o = $json.output;
  const deals = $('Aggregate').first().json.deals;
  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const money = n => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ' грн';
  const total = deals.reduce((s, d) => s + (Number(d.Amount) || 0), 0);
  const cnt = c => deals.filter(d => d.Category === c).length;
  const lines = [];
  lines.push('📈 <b>CEO FORECAST</b>');
  lines.push('📅 Тиждень до ' + $now.toFormat('dd.MM.yyyy'));
  lines.push('');
  lines.push(esc(o.headline));
  lines.push('');
  lines.push('<b>📊 Портфель під контролем</b>');
  lines.push(deals.length + ' угод на ' + money(total));
  lines.push('🔴 Critical: ' + cnt('Critical') + ' · 🟡 Medium: ' + cnt('Medium') + ' · 🟢 Normal: ' + cnt('Normal'));
  lines.push('');
  lines.push('<b>💰 Прогноз закриття (30 днів)</b>');
  lines.push('Реалістичний: <b>' + money(o.expected_amount) + '</b>');
  lines.push('Оптимістичний: ' + money(o.best_case_amount));
  lines.push('Песимістичний: ' + money(o.worst_case_amount));
  lines.push('');
  lines.push('<b>✅ Найімовірніше закриються</b>');
  o.likely_deals.forEach(d => lines.push('• <b>' + esc(d.deal_name) + '</b> — ' + money(d.amount) + ' (' + d.probability_pct + '%): ' + esc(d.reason)));
  lines.push('');
  lines.push('<b>🚨 ТОП-3 ризики</b>');
  o.top_risks.forEach((d, i) => lines.push((i + 1) + '. <b>' + esc(d.deal_name) + '</b> — ' + money(d.amount) + '\n' + esc(d.risk)));
  lines.push('');
  lines.push('<b>🎯 Рішення на тиждень</b>');
  o.recommendations.forEach((x, i) => lines.push((i + 1) + '. ' + esc(x)));
  return lines.join('\n');
})() }}
